       100 * SUM(QT_MAT_PROF_TEC) / SUM(QT_MAT_BAS) AS percentual_profissional_tecnica
FROM matriculas;

SELECT SUM(QT_MAT_PROF_TEC), 
       SUM(QT_MAT_PROF_TEC) / SUM(QT_MAT_BAS) * 100 AS PERCENTUAL 
FROM matriculas;

SELECT SUM(QT_MAT_BAS_LIBRAS) AS total_nacional
FROM matriculas
